<body>

    <header>
        <h1><i data-lucide="shuffle"></i> Caption Mixer</h1>
    </header>

    <div class="grid-layout">

        <!-- Controls Matrix -->
        <section class="card">
            <h2>Campaign Controls</h2>

            <div class="form-group">
                <label for="goal">Campaign Goal</label>
                <select id="goal" onchange="mixIngredients()">
                    <option value="">-- Select Goal --</option>
                    <option value="conversion">Conversion / Sales</option>
                    <option value="engagement">Community Engagement</option>
                    <option value="education">Value / Education</option>
                    <option value="brand">Brand Awareness</option>
                </select>
            </div>

            <div class="form-group">
                <label for="audience">Target Audience</label>
                <select id="audience" onchange="mixIngredients()">
                    <option value="">-- Select Audience --</option>
                    <option value="cold">Cold (Unaware / Problem Aware)</option>
                    <option value="warm">Warm (Solution Aware / Retargeting)</option>
                    <option value="hot">Hot (Existing Customers / Fans)</option>
                </select>
            </div>

            <div class="form-group">
                <label for="asset">Creative Asset Type</label>
                <select id="asset" onchange="mixIngredients()">
                    <option value="">-- Select Asset --</option>
                    <option value="video">Short-Form Video (Reel/TikTok)</option>
                    <option value="carousel">Carousel / Info-graphic</option>
                    <option value="image">Static Image / Photo</option>
                </select>
            </div>

            <div class="form-group">
                <label for="cta">Primary Call To Action</label>
                <select id="cta" onchange="mixIngredients()">
                    <option value="">-- Select CTA --</option>
                    <option value="link">Click Link in Bio / Description</option>
                    <option value="comment">Comment Specific Keyword</option>
                    <option value="save">Save / Share this Post</option>
                    <option value="dm">Send a Direct Message</option>
                </select>
            </div>

            <div class="form-group">
                <label for="freshness">Freshness Limit (Days Live)</label>
                <input type="number" id="freshness" min="1" max="90" value="7" oninput="mixIngredients()">
            </div>
        </section>

        <!-- Warnings Output -->
        <div id="warningBox" class="warning-box"></div>

        <!-- Ingredients Output -->
        <section class="card">
            <h2>Caption Ingredients</h2>
            <div id="ingredientsContainer" class="ingredients-container">
                <p style="color: var(--text-muted); text-align: center; padding: 20px 0;">Select criteria above to generate ingredients.</p>
            </div>
        </section>

        <!-- Brief Blueprint -->
        <section class="card">
            <h2>Offline Brief Blueprint</h2>
            <div id="briefBox" class="brief-box">Select all controls to generate the structured campaign brief blueprint.</div>
            <button class="btn" id="copyBtn" onclick="copyBrief()"><i data-lucide="copy"></i> Copy Brief to Clipboard</button>
        </section>
    </div>

    <script>
        // Data matrix maps configurations to ingredient variants
        const matrix = {
            goal: {
                conversion: { hook: "The Hard Truth", body: "Direct problem-solution transformation presentation.", structural: "Scarcity or incentive anchor" },
                engagement: { hook: "Unpopular Opinion / Question", body: "Relatable storytelling or interactive debate prompt.", structural: "Open-ended loop closure" },
                education: { hook: "The Step-by-Step Breakdown", body: "Actionable, value-first insights stripped of fluff.", structural: "Bullet-point formatting priority" },
                brand: { hook: "Behind the Curtain", body: "Core values, origin insights, or high-level philosophy.", structural: "Core identity positioning statement" }
            },
            audience: {
                cold: { tone: "Problem-Agitating & Clear", depth: "Low-context baseline; clear definitions, high readability." },
                warm: { tone: "Trust-Building & Credible", depth: "Mid-context calibration; presumes solution familiarity." },
                hot: { tone: "Direct & Community-Driven", depth: "High-context shorthand; rewards loyalty, immediate value." }
            },
            asset: {
                video: { sync: "Visual Handshake", requirement: "First 3 seconds must map directly to the text hook line." },
                carousel: { sync: "Pacing Continuation", requirement: "Caption expands on slide data rather than repeating it." },
                image: { sync: "Context Anchoring", requirement: "Caption does the heavy lifting; structural depth required." }
            },
            cta: {
                link: { anchor: "Bio Navigation Direction", phrasing: "Tap the link in bio to secure yours." },
                comment: { anchor: "Automation Trigger Phrase", phrasing: "Comment [KEYWORD] below and check your DMs." },
                save: { anchor: "Value Retention Reminder", phrasing: "Save this post so you can reference it later." },
                dm: { anchor: "Conversational Bridge", phrasing: "Send me a DM with the word [START] to chat." }
            }
        };

        function mixIngredients() {
            const goal = document.getElementById('goal').value;
            const audience = document.getElementById('audience').value;
            const asset = document.getElementById('asset').value;
            const cta = document.getElementById('cta').value;
            const freshness = document.getElementById('freshness').value || 7;

            const warningBox = document.getElementById('warningBox');
            const container = document.getElementById('ingredientsContainer');
            const briefBox = document.getElementById('briefBox');

            // Handle Missing Piece Warnings
            let warningsHtml = '';
            if (!goal) warningsHtml += `<div class="warning-item"><i data-lucide="alert-triangle"></i> Missing Campaign Goal</div>`;
            if (!audience) warningsHtml += `<div class="warning-item"><i data-lucide="alert-triangle"></i> Missing Target Audience</div>`;
            if (!asset) warningsHtml += `<div class="warning-item"><i data-lucide="alert-triangle"></i> Missing Creative Asset Type</div>`;
            if (!cta) warningsHtml += `<div class="warning-item"><i data-lucide="alert-triangle"></i> Missing Call To Action</div>`;

            if (warningsHtml) {
                warningBox.innerHTML = warningsHtml;
                warningBox.style.display = 'block';
                lucide.createIcons();
            } else {
                warningBox.style.display = 'none';
            }

            // If empty, reset downstream outputs
            if (!goal && !audience && !asset && !cta) {
                container.innerHTML = '<p style="color: var(--text-muted); text-align: center; padding: 20px 0;">Select criteria above to generate ingredients.</p>';
                briefBox.innerText = 'Select all controls to generate the structured campaign brief blueprint.';
                return;
            }

            // Generate Active Ingredient Cards
            let cardsHtml = '';

            if (goal) {
                const gData = matrix.goal[goal];
                cardsHtml += `
                    <div class="ingredient-card">
                        <div class="ing-header"><span>Goal Strategy</span><span>${goal}</span></div>
                        <div class="ing-title">${gData.hook} Hook</div>
                        <div class="ing-desc">${gData.body}</div>
                        <div class="pill-group"><span class="pill">Structural: ${gData.structural}</span></div>
                    </div>`;
            }

            if (audience) {
                const aData = matrix.audience[audience];
                cardsHtml += `
                    <div class="ingredient-card">
                        <div class="ing-header"><span>Audience Layer</span><span>${audience}</span></div>
                        <div class="ing-title">${aData.tone}</div>
                        <div class="ing-desc">Depth Configuration: ${aData.depth}</div>
                    </div>`;
            }

            if (asset) {
                const asData = matrix.asset[asset];
                cardsHtml += `
                    <div class="ingredient-card">
                        <div class="ing-header"><span>Asset Sync</span><span>${asset}</span></div>
                        <div class="ing-title">${asData.sync}</div>
                        <div class="ing-desc">${asData.requirement}</div>
                    </div>`;
            }

            if (cta) {
                const cData = matrix.cta[cta];
                cardsHtml += `
                    <div class="ingredient-card">
                        <div class="ing-header"><span>CTA Mechanics</span><span>${cta}</span></div>
                        <div class="ing-title">${cData.anchor}</div>
                        <div class="ing-desc">Execution Phrasing: "${cData.phrasing}"</div>
                    </div>`;
            }

            // Add Freshness Decay Warning Check
            if (freshness > 14) {
                cardsHtml += `
                    <div class="ingredient-card warning">
                        <div class="ing-header"><span style="color: var(--accent);">Freshness Alert</span><span>${freshness} Days</span></div>
                        <div class="ing-title" style="color: var(--accent);">High Fatigue Risk</div>
                        <div class="ing-desc">Content live for over 14 days requires dynamic comment monitoring or alternate angle variants to prevent performance degradation.</div>
                    </div>`;
            }

            container.innerHTML = cardsHtml;

            // Generate Copyable Offline Brief
            if (goal && audience && asset && cta) {
                const g = matrix.goal[goal];
                const a = matrix.audience[audience];
                const ast = matrix.asset[asset];
                const c = matrix.cta[cta];

                briefBox.innerText = 
`=== CAMPAIGN CAPTION BRIEF BLUEPRINT ===
Generated: ${new Date().toLocaleDateString()}
Campaign Lifecycle: ${freshness} Days Limit

[CONTROLS ARCHITECTURE]
• Goal: ${goal.toUpperCase()} -> Strategy: ${g.hook}
• Audience: ${audience.toUpperCase()} -> Tone: ${a.tone}
• Asset Structure: ${asset.toUpperCase()} -> Matrix Requirement: ${ast.sync}
• CTA Strategy: ${cta.toUpperCase()} -> Action: ${c.anchor}

[INGREDIENT BLUEPRINT MIX]
1. HOOK COMPONENT:
   Focus: ${g.hook}
   Guideline: Must match the asset's "${ast.sync}" principle.

2. BODY COMPONENT:
   Framework: ${g.body}
   Context Depth: ${a.depth}

3. STRUCTURAL ANCHOR:
   Requirement: ${g.structural}

4. TERMINAL ACTION (CTA):
   Execution Phrasing: "${c.phrasing}"

[OFFLINE QUALITY CHECKLIST]
[ ] Caption length matches asset type guidelines.
[ ] Asset payload delivers on the primary text hook within 3 seconds.
[ ] CTA matches terminal objective exactly.
======================================`;
            } else {
                briefBox.innerText = 'Awaiting all controls execution to compile the unified brief blueprint...';
            }
        }

        function copyBrief() {
            const briefText = document.getElementById('briefBox').innerText;
            const copyBtn = document.getElementById('copyBtn');

            if (document.getElementById('goal').value && 
                document.getElementById('audience').value && 
                document.getElementById('asset').value && 
                document.getElementById('cta').value) {

                navigator.clipboard.writeText(briefText).then(() => {
                    copyBtn.classList.add('copied');
                    copyBtn.innerHTML = `<i data-lucide="check"></i> Brief Copied!`;
                    lucide.createIcons();

                    setTimeout(() => {
                        copyBtn.classList.remove('copied');
                        copyBtn.innerHTML = `<i data-lucide="copy"></i> Copy Brief to Clipboard`;
                        lucide.createIcons();
                    }, 2000);
                });
            }
        }

        // Initial icon rendering
        lucide.createIcons();
    </script>
</body>
</html>

