        <div id="warningBox" class="warning-box"></div>

        <section class="card">
            <h2>Caption Ingredients</h2>
            <div id="ingredientsContainer" class="ingredients-container"></div>
        </section>

        <section class="card">
            <h2>Offline Brief Blueprint</h2>
            <div id="briefBox" class="brief-box"></div>
            <button class="btn" id="copyBtn">Copy Brief to Clipboard</button>
        </section>
    </div>

    <script>
        const matrix = {
            goal: {
                conversion: { hook: "The Hard Truth", body: "Direct problem-solution transformation presentation.", structural: "Scarcity or incentive anchor" },
                engagement: { hook: "Unpopular Opinion / Question", body: "Relatable storytelling or interactive debate prompt.", structural: "Open-ended loop closure" },
                education: { hook: "The Step-by-Step Breakdown", body: "Actionable, value-first insights stripped of fluff.", structural: "Bullet-point formatting priority" },
                brand: { hook: "Behind the Curtain", body: "Core values, origin insights, or high-level philosophy.", structural: "Core identity positioning statement" }
            },
            audience: {
                cold: { tone: "Problem-Agitating & Clear", depth: "Low-context baseline; clear definitions, high readability." },
                warm: { tone: "Trust-Building & Credible", depth: "Mid-context calibration; presumes solution familiarity." },
                hot: { tone: "Direct & Community-Driven", depth: "High-context shorthand; rewards loyalty, immediate value." }
            },
            asset: {
                video: { sync: "Visual Handshake", requirement: "First 3 seconds must map directly to the text hook line." },
                carousel: { sync: "Pacing Continuation", requirement: "Caption expands on slide data rather than repeating it." },
                image: { sync: "Context Anchoring", requirement: "Caption does the heavy lifting; structural depth required." }
            },
            cta: {
                link: { anchor: "Bio Navigation Direction", phrasing: "Tap the link in bio to secure yours." },
                comment: { anchor: "Automation Trigger Phrase", phrasing: "Comment [KEYWORD] below and check your DMs." },
                save: { anchor: "Value Retention Reminder", phrasing: "Save this post so you can reference it later." },
                dm: { anchor: "Conversational Bridge", phrasing: "Send me a DM with the word [START] to chat." }
            }
        };

        const selectGoal = document.getElementById('goal');
        const selectAudience = document.getElementById('audience');
        const selectAsset = document.getElementById('asset');
        const selectCta = document.getElementById('cta');
        const inputFreshness = document.getElementById('freshness');

        const warningBox = document.getElementById('warningBox');
        const ingredientsContainer = document.getElementById('ingredientsContainer');
        const briefBox = document.getElementById('briefBox');
        const copyBtn = document.getElementById('copyBtn');

        function createIngredientCard(layerName, typeValue, titleText, descText, pillText = null, isWarning = false) {
            const card = document.createElement('div');
            card.className = isWarning ? 'ingredient-card warning' : 'ingredient-card';

            const header = document.createElement('div');
            header.className = 'ing-header';

            const spanLayer = document.createElement('span');
            spanLayer.textContent = layerName;

            const spanType = document.createElement('span');
            spanType.textContent = typeValue;

            header.appendChild(spanLayer);
            header.appendChild(spanType);

            const title = document.createElement('div');
            title.className = 'ing-title';
            title.textContent = titleText;

            const desc = document.createElement('div');
            desc.className = 'ing-desc';
            desc.textContent = descText;

            card.appendChild(header);
            card.appendChild(title);
            card.appendChild(desc);

            if (pillText) {
                const pillGroup = document.createElement('div');
                pillGroup.className = 'pill-group';
                const pill = document.createElement('span');
                pill.className = 'pill';
                pill.textContent = pillText;
                pillGroup.appendChild(pill);
                card.appendChild(pillGroup);
            }

            return card;
        }

        function createWarningItem(text) {
            const item = document.createElement('div');
            item.className = 'warning-item';
            item.textContent = `⚠ ${text}`;
            return item;
        }

        function mixIngredients() {
            const goal = selectGoal.value;
            const audience = selectAudience.value;
            const asset = selectAsset.value;
            const cta = selectCta.value;
            const freshness = parseInt(inputFreshness.value, 10) || 7;

            // Clean previous nodes
            warningBox.textContent = '';
            ingredientsContainer.textContent = '';
            briefBox.textContent = '';

            let missingPieces = 0;

            if (!goal) { warningBox.appendChild(createWarningItem('Missing Campaign Goal')); missingPieces++; }
            if (!audience) { warningBox.appendChild(createWarningItem('Missing Target Audience')); missingPieces++; }
            if (!asset) { warningBox.appendChild(createWarningItem('Missing Creative Asset Type')); missingPieces++; }
            if (!cta) { warningBox.appendChild(createWarningItem('Missing Call To Action')); missingPieces++; }

            if (missingPieces > 0) {
                warningBox.style.display = 'block';
            } else {
                warningBox.style.display = 'none';
            }

            if (missingPieces === 4) {
                const placeholder = document.createElement('p');
                placeholder.className = 'placeholder-text';
                placeholder.textContent = 'Select criteria above to generate ingredients.';
                ingredientsContainer.appendChild(placeholder);
                briefBox.textContent = 'Select all controls to generate the structured campaign brief blueprint.';
                return;
            }

            if (goal) {
                const gData = matrix.goal[goal];
                ingredientsContainer.appendChild(createIngredientCard('Goal Strategy', goal, `${gData.hook} Hook`, gData.body, `Structural: ${gData.structural}`));
            }

            if (audience) {
                const aData = matrix.audience[audience];
                ingredientsContainer.appendChild(createIngredientCard('Audience Layer', audience, aData.tone, `Depth Configuration: ${aData.depth}`));
            }

            if (asset) {
                const asData = matrix.asset[asset];
                ingredientsContainer.appendChild(createIngredientCard('Asset Sync', asset, asData.sync, asData.requirement));
            }

            if (cta) {
                const cData = matrix.cta[cta];
                ingredientsContainer.appendChild(createIngredientCard('CTA Mechanics', cta, cData.anchor, `Execution Phrasing: "${cData.phrasing}"`));
            }

            if (freshness > 14) {
                ingredientsContainer.appendChild(createIngredientCard('Freshness Alert', `${freshness} Days`, 'High Fatigue Risk', 'Content live for over 14 days requires dynamic comment monitoring or alternate angle variants to prevent performance degradation.', null, true));
            }

            if (missingPieces === 0) {
                const g = matrix.goal[goal];
                const a = matrix.audience[audience];
                const ast = matrix.asset[asset];
                const c = matrix.cta[cta];

                briefBox.textContent = 
`=== CAMPAIGN CAPTION BRIEF BLUEPRINT ===
Generated On: ${new Date().toLocaleDateString()}
Campaign Lifecycle: ${freshness} Days Limit

[CONTROLS ARCHITECTURE]
• Goal: ${goal.toUpperCase()} -> Strategy: ${g.hook}
• Audience: ${audience.toUpperCase()} -> Tone: ${a.tone}
• Asset Structure: ${asset.toUpperCase()} -> Matrix Requirement: ${ast.sync}
• CTA Strategy: ${cta.toUpperCase()} -> Action: ${c.anchor}

[INGREDIENT BLUEPRINT MIX]
1. HOOK COMPONENT:
   Focus: ${g.hook}
   Guideline: Must match the asset's "${ast.sync}" principle.

2. BODY COMPONENT:
   Framework: ${g.body}
   Context Depth: ${a.depth}

3. STRUCTURAL ANCHOR:
   Requirement: ${g.structural}

4. TERMINAL ACTION (CTA):
   Execution Phrasing: "${c.phrasing}"

[OFFLINE QUALITY CHECKLIST]
[ ] Caption length matches asset type guidelines.
[ ] Asset payload delivers on the primary text hook within 3 seconds.
[ ] CTA matches terminal objective exactly.
======================================`;
            } else {
                briefBox.textContent = 'Awaiting all controls execution to compile the unified brief blueprint...';
            }
        }

        function copyBrief() {
            if (!selectGoal.value || !selectAudience.value || !selectAsset.value || !selectCta.value) return;

            navigator.clipboard.writeText(briefBox.textContent).then(() => {
                copyBtn.classList.add('copied');
                copyBtn.textContent = 'Brief Copied!';

                setTimeout(() => {
                    copyBtn.classList.remove('copied');
                    copyBtn.textContent = 'Copy Brief to Clipboard';
                }, 2000);
            });
        }

        selectGoal.addEventListener('change', mixIngredients);
        selectAudience.addEventListener('change', mixIngredients);
        selectAsset.addEventListener('change', mixIngredients);
        selectCta.addEventListener('change', mixIngredients);
        inputFreshness.addEventListener('input', mixIngredients);
        copyBtn.addEventListener('click', copyBrief);

        // Run baseline render pass on boot
        mixIngredients();
    </script>
</body>
</html>
